20	package ca.uhn.fhir.jpa.migrate.taskdef;
21	
22	import ca.uhn.fhir.jpa.migrate.DriverTypeEnum;
23	import ca.uhn.fhir.jpa.migrate.JdbcUtils;
24	import jakarta.annotation.Nonnull;
25	import org.apache.commons.lang3.Validate;
26	import org.apache.commons.lang3.builder.EqualsBuilder;
27	import org.apache.commons.lang3.builder.HashCodeBuilder;
