43	public class DropIndexTask extends BaseTableTask {
44	
45		private static final Logger ourLog = LoggerFactory.getLogger(DropIndexTask.class);
46		private String myIndexName;
47		private boolean myOnline;
48	
49		public DropIndexTask(String theProductVersion, String theSchemaVersion) {
50			super(theProductVersion, theSchemaVersion);
51		}
52	
53		List<String> generateSql() throws SQLException {
54			Validate.notBlank(myIndexName, "indexName must not be blank");
55			Validate.notBlank(getTableName(), "tableName must not be blank");
56	
57			if (!JdbcUtils.getIndexNames(getConnectionProperties(), getTableName()).contains(myIndexName)) {
58				return Collections.emptyList();
59			}
60			boolean isUnique = JdbcUtils.isIndexUnique(getConnectionProperties(), getTableName(), myIndexName);
61	
62			return doGenerateSql(isUnique);
63		}
64	
65		// testable without jdbc
66		@Nonnull
67		List<String> doGenerateSql(boolean isUnique) {
68			DriverTypeEnum driverType = getDriverType();
69			List<String> sql = new ArrayList<>();
70	
71			if (isUnique) {
72				// Drop constraint
73				switch (driverType) {
74					case MYSQL_5_7:
75					case MARIADB_10_1:
76						// Need to quote the index name as the word "PRIMARY" is reserved in MySQL
77						sql.add("alter table " + getTableName() + " drop index `" + myIndexName + "`");
78						break;
79					case H2_EMBEDDED:
80						sql.add("drop index " + myIndexName);
81						break;
82					case DERBY_EMBEDDED:
83						sql.add("alter table " + getTableName() + " drop constraint " + myIndexName);
84						break;
85					case ORACLE_12C:
86						sql.add("drop index " + myIndexName + (myOnline ? " ONLINE" : ""));
87						break;
88					case MSSQL_2012:
89						sql.add("drop index " + myIndexName + " on " + getTableName()
90								+ (myOnline ? " WITH (ONLINE = ON)" : ""));
91						break;
92					case POSTGRES_9_4:
93						sql.add("alter table " + getTableName() + " drop constraint if exists " + myIndexName + " cascade");
94						sql.add("drop index " + (myOnline ? "CONCURRENTLY " : "") + "if exists " + myIndexName
95								+ " cascade");
96						setTransactional(!myOnline);
97						break;
98					case COCKROACHDB_21_1:
99						sql.add("drop index if exists " + getTableName() + "@" + myIndexName + " cascade");
100						break;
101				}
102			} else {
103				// Drop index
104				switch (driverType) {
105					case MYSQL_5_7:
106					case MARIADB_10_1:
107						sql.add("alter table " + getTableName() + " drop index " + myIndexName);
108						break;
109					case POSTGRES_9_4:
110						sql.add("drop index " + (myOnline ? "CONCURRENTLY " : "") + myIndexName);
111						setTransactional(!myOnline);
112						break;
113					case DERBY_EMBEDDED:
114					case H2_EMBEDDED:
115						sql.add("drop index " + myIndexName);
116						break;
117					case ORACLE_12C:
118						sql.add("drop index " + myIndexName + (myOnline ? " ONLINE" : ""));
119						break;
120					case MSSQL_2012:
121						sql.add("drop index " + getTableName() + "." + myIndexName);
122						break;
123					case COCKROACHDB_21_1:
124						sql.add("drop index " + getTableName() + "@" + myIndexName);
125						break;
126				}
127			}
128			return sql;
129		}
130	
131		@Override
132		public void validate() {
133			super.validate();
134			Validate.notBlank(myIndexName, "The index name must not be blank");
135	
136			setDescription("Drop index " + myIndexName + " from table " + getTableName());
137		}
138	
139		@Override
140		public void doExecute() throws SQLException {
141			/*
142			 * Derby and H2 both behave a bit weirdly if you create a unique constraint
143			 * using the @UniqueConstraint annotation in hibernate - They will create a
144			 * constraint with that name, but will then create a shadow index with a different
145			 * name, and it's that different name that gets reported when you query for the
146			 * list of indexes.
147			 *
148			 * For example, on H2 if you create a constraint named "IDX_FOO", the system
149			 * will create an index named "IDX_FOO_INDEX_A" and a constraint named "IDX_FOO".
150			 *
151			 * The following is a solution that uses appropriate native queries to detect
152			 * on the given platforms whether an index name actually corresponds to a
153			 * constraint, and delete that constraint.
154			 */
155	
156			if (getDriverType() == DriverTypeEnum.H2_EMBEDDED) {
157				@Language("SQL")
158				String findConstraintSql =
159						"SELECT DISTINCT constraint_name FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE constraint_name = ? AND table_name = ?";
160				@Language("SQL")
161				String dropConstraintSql = "ALTER TABLE " + getTableName() + " DROP CONSTRAINT ?";
162				findAndDropConstraint(findConstraintSql, dropConstraintSql);
163			} else if (getDriverType() == DriverTypeEnum.DERBY_EMBEDDED) {
164				@Language("SQL")
165				String findConstraintSql =
166						"SELECT c.constraintname FROM sys.sysconstraints c, sys.systables t WHERE c.tableid = t.tableid AND c.constraintname = ? AND t.tablename = ?";
167				@Language("SQL")
168				String dropConstraintSql = "ALTER TABLE " + getTableName() + " DROP CONSTRAINT ?";
169				findAndDropConstraint(findConstraintSql, dropConstraintSql);
170			} else if (getDriverType() == DriverTypeEnum.ORACLE_12C) {
171				@Language("SQL")
172				String findConstraintSql =
173						"SELECT constraint_name FROM user_constraints WHERE constraint_name = ? AND table_name = ?";
174				@Language("SQL")
175				String dropConstraintSql = "ALTER TABLE " + getTableName() + " DROP CONSTRAINT ?";
176				findAndDropConstraint(findConstraintSql, dropConstraintSql);
177			} else if (getDriverType() == DriverTypeEnum.MSSQL_2012) {
178				// Legacy deletion for SQL Server unique indexes
179				@Language("SQL")
180				String findConstraintSql =
181						"SELECT tc.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS AS tc WHERE tc.CONSTRAINT_NAME = ? AND tc.TABLE_NAME = ?";
182				@Language("SQL")
183				String dropConstraintSql = "ALTER TABLE " + getTableName() + " DROP CONSTRAINT ?";
184				findAndDropConstraint(findConstraintSql, dropConstraintSql);
185			}
186	
187			Set<String> indexNames = JdbcUtils.getIndexNames(getConnectionProperties(), getTableName());
188	
189			if (!indexNames.contains(myIndexName)) {
190				logInfo(ourLog, "Index {} does not exist on table {} - No action needed", myIndexName, getTableName());
191				return;
192			}
